import { describe, expect, it, vi } from 'vitest';
import { EventEmitter } from 'node:events';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
const state = vi.hoisted(() => ({ spawn: vi.fn(), args: [] as string[] }));
vi.mock('node:child_process', () => ({ spawn: state.spawn }));
import { separationManifestSchema, runAudioSeparation } from '../lib/audio/separation';
import { globalAmtWorkerPool } from '../lib/audio/transcription/server';
import { evaluateDistributedPreanalysis, buildDistributedWindowRanges } from '../lib/audio/iatpe/engine';
import { fixture } from '../tests/fixtures';
import { transcribeStems } from '../lib/audio/transcription/stems';
import { writeMidi } from '../lib/music/midi-writer';
import { parseMidi } from 'midi-file';
import { writeMusicXML } from '../lib/music/musicxml';
import { validateMusicXML } from '../lib/music/notation-validation';
import { LookaheadMetronome } from '../lib/audio/metronome';
import { computeBarsAndBeats } from '../lib/music/tempo-map';
import type { AudioAssetMetadata } from '../lib/audio/iatpe/types';
const evidence: Record<string, unknown> = {};

describe('Audit diagnostics: asserts observed behavior, not release acceptance', () => {
  it('reproduces the Python/TypeScript manifest mismatch and dropped metadata', async () => {
    const raw = JSON.parse(await readFile('.tmp/system-audit-2026-10-15-roformer-manifest.json', 'utf8'));
    const parsed = separationManifestSchema.safeParse(raw);
    expect(parsed.success).toBe(false);
    const canonical = separationManifestSchema.parse({ ...raw, model: 'bs_roformer' });
    evidence.manifestContract = {
      returnedModel: raw.model,
      rejected: !parsed.success,
      issues: parsed.success ? [] : parsed.error.issues.map(x => ({ path:x.path, code:x.code })),
      pythonHasTelemetry: !!raw.telemetry,
      telemetryRetainedBySchema: 'telemetry' in canonical,
      sha256RetainedBySchema: 'sha256' in canonical.sources[0],
    };
  });

  it('shows that repeated samples can be considered representative by the new helper', () => {
    const repeated = Array.from({ length:3 }, () => ({
      label:'intro' as const, startSeconds:0, endSeconds:6, rmsDb:-15,
      spectralCentroidHz:1000, harmonicRatio:.8, transientDensity:.1, scores:{piano:.9},
    }));
    const result = evaluateDistributedPreanalysis(300, repeated);
    expect(result.isConfirmedSoloInstrument).toBe(true);
    evidence.distributedHelper = {
      rangesFor300Seconds: buildDistributedWindowRanges(300),
      acceptsThreeIdenticalIntroWindowsAsRepresentative: result.isConfirmedSoloInstrument,
    };
  });

  it('checks that the AMT pool caches callback results without owning a worker', async () => {
    const stem: AudioAssetMetadata = {
      id:'owner-a-stem', kind:'piano',label:'Piano',file:'a.wav',engine:'demucs',
      checkpoint:'model-a',sampleRate:44100,durationSeconds:1,sha256:'a'.repeat(64),
      gain:1,rms:.1,confidence:0,transcriptionEligible:true,level:1,
    };
    let calls = 0;
    const infer = async () => { calls++; return [{startSeconds:0,durationSeconds:.2,midiPitch:60,velocity:90,confidence:1}]; };
    const first = await globalAmtWorkerPool.transcribeStem({stem,globalTempoBpm:120}, infer);
    const second = await globalAmtWorkerPool.transcribeStem({
      stem:{...stem,id:'owner-b-stem',file:'b.wav',checkpoint:'model-b'},globalTempoBpm:120,
    }, infer);
    expect(calls).toBe(1);
    expect(second.stemId).toBe('owner-a-stem');
    evidence.amtPool = {
      callbacksInvoked:calls, firstWorkerReuseClaim:first.reusedPersistentWorker,
      secondCacheHit:second.cacheHit, requestedSecondStem:'owner-b-stem',
      returnedSecondStem:second.stemId, stats:globalAmtWorkerPool.getStats(),
    };
  });

  it('captures engine downgrade, split stderr loss and output-directory cache reuse in the new wrapper', async () => {
    vi.stubEnv('VERCEL', '');
    const dir = join(process.cwd(), '.tmp/system-audit-wrapper-2026-10-15');
    await mkdir(dir, {recursive:true});
    const input = join(dir, 'input.bin');
    await writeFile(input, 'isolated controlled audio identity for wrapper audit');
    const stem: AudioAssetMetadata = {
      id:'drums',kind:'drums',label:'Drums',file:'drums.wav',engine:'demucs',checkpoint:'htdemucs_6s',
      sampleRate:44100,durationSeconds:1,sha256:'b'.repeat(64),gain:1,rms:.1,confidence:0,
      transcriptionEligible:false,level:1,
    };
    state.spawn.mockImplementation((_cmd:string,args:string[]) => {
      state.args = args;
      const child = Object.assign(new EventEmitter(), {
        stdout:new EventEmitter(), stderr:new EventEmitter(), kill:vi.fn(),
      });
      setTimeout(() => {
        const event = JSON.stringify({event:'stem_ready',stem})+'\n';
        const cut = Math.floor(event.length/2);
        child.stderr.emit('data',Buffer.from(event.slice(0,cut)));
        child.stderr.emit('data',Buffer.from(event.slice(cut)));
        child.stdout.emit('data',Buffer.from(JSON.stringify({
          model:'htdemucs_6s',engine:'demucs',sources:[stem],durationSeconds:1,gain:1,warnings:[],telemetry:{},
        })));
        child.emit('close',0);
      },0);
      return child;
    });
    const ready = vi.fn();
    const options = { inputPath:input,outputDir:join(dir,'job-a'),model:'bs_roformer' as const,onStemReady:ready };
    await runAudioSeparation(options);
    const firstEvents = ready.mock.calls.length;
    const cached = await runAudioSeparation({...options,outputDir:join(dir,'job-b')});
    expect(state.spawn).toHaveBeenCalledTimes(1);
    expect(firstEvents).toBe(0);
    evidence.separationWrapper = {
      requestedEngine:options.model, spawnedScript:state.args[0],
      spawnedModel:state.args[state.args.indexOf('--model')+1],
      firstStemEventsDelivered:firstEvents,
      secondDifferentDirectoryCacheHit:cached.telemetry.cacheHit,
      processStarts:state.spawn.mock.calls.length,
    };
    vi.unstubAllEnvs();
  });

  it('rechecks MIDI ports, FX XML and metronome scheduling', async () => {
    const global = {...fixture(),provenance:'transcription' as const};
    const stems = Array.from({length:17},(_,i)=>({
      id:'source-'+i,kind:'piano' as const,label:'Piano '+i,confidence:0,program:i,
      storagePath:'piano-'+i+'.wav',localPath:'piano-'+i+'.wav',
    }));
    const merged = await transcribeStems(global,stems,async()=>global);
    const midi = parseMidi(writeMidi(merged));
    evidence.midi = {
      ports:merged.sources.map(s=>s.port),
      exportedPortEvents:midi.tracks.flat().filter(e=>e.type==='portPrefix').length,
    };
    const fx = fixture();
    fx.sources[0].category = 'noise';
    fx.events = [{...fx.events[0],type:'drum',notehead:'cross',lyric:'Efecto',articulation:'accent'}];
    const xml = writeMusicXML(fx);
    evidence.fx = {unpitched:xml.includes('<unpitched>'),pitched:xml.includes('<pitch>'),localValidation:validateMusicXML(xml)};
    const scheduled:number[] = [];
    const ctx:any = {
      currentTime:0,state:'running',destination:{},
      createGain:()=>({gain:{setValueAtTime(){},linearRampToValueAtTime(){},exponentialRampToValueAtTime(){}},connect(){},disconnect(){}}),
      createOscillator:()=>({frequency:{setValueAtTime(){}},connect(){},start(t:number){scheduled.push(t)},stop(){}}),
    };
    vi.stubGlobal('window',{AudioContext:function(){},setInterval:()=>1,clearInterval(){}});
    try {
      const metro = new LookaheadMetronome(ctx);
      metro.updateBars(computeBarsAndBeats([{startSeconds:0,bpm:120,confidence:1}],2,[4,4]));
      ctx.currentTime=.38; metro.start(.38);
      for (const t of [.38,.40,.42,.44,.46]) {ctx.currentTime=t;metro.seek(t);(metro as any).scheduleLoop();}
      metro.destroy();
      evidence.metronome = {scheduled,expectedClicksAtHalfSecond:1};
      expect(scheduled.length).toBe(5);
    } finally {vi.unstubAllGlobals();}
    await writeFile('.tmp/system-audit-2026-10-15-typescript.json',JSON.stringify(evidence,null,2));
  });
});

